-- ~/.config/hypr/conf/display.lua
-- Normally you do not edit this file: SUPER + I > Display changes resolution, scale, rotation, position and mirroring,
-- and saves them in ~/.local/state/krmv-setup/monitors.tsv, which is read here at every login.
-- Find your monitor name with: hyprctl monitors
hl.monitor({
  output   = "",            -- "" = all monitors that have no rule of their own
  mode     = "preferred",   -- or e.g. "1920x1080@144"
  position = "auto",
  scale    = 1,
})

local f = io.open((os.getenv("HOME") or "") .. "/.local/state/krmv-setup/monitors.tsv", "r")
if f then
  for line in f:lines() do
    local n, m, p, s, t, mi = line:match("^([^\t]*)\t([^\t]*)\t([^\t]*)\t([^\t]*)\t([^\t]*)\t?(.*)$")
    if n and n ~= "" then
      local rule = {
        output = n, mode = m, position = p,
        scale = (s == "auto") and "auto" or (tonumber(s) or 1),
        transform = tonumber(t) or 0,
      }
      if mi and mi ~= "" then rule.mirror = mi end
      hl.monitor(rule)
    end
  end
  f:close()
end
